import{_ as o,o as l,c as a,a2 as t}from"./chunks/framework.D0_YsCyK.js";const x=JSON.parse('{"title":"S 改名：FLVX → FLMX（含仓库 flvx-max → flmx-max）（2026-10-20，版本 1.0.24）","description":"","frontmatter":{},"headers":[],"relativePath":"audit/S-flmx-rename.md","filePath":"audit/S-flmx-rename.md","lastUpdated":1792503657000}'),i={name:"audit/S-flmx-rename.md"};function d(c,e,n,s,r,f){return l(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="s-改名-flvx-→-flmx-含仓库-flvx-max-→-flmx-max-2026-10-20-版本-1-0-24" tabindex="-1">S 改名：FLVX → FLMX（含仓库 flvx-max → flmx-max）（2026-10-20，版本 1.0.24） <a class="header-anchor" href="#s-改名-flvx-→-flmx-含仓库-flvx-max-→-flmx-max-2026-10-20-版本-1-0-24" aria-label="Permalink to &quot;S 改名：FLVX → FLMX（含仓库 flvx-max → flmx-max）（2026-10-20，版本 1.0.24）&quot;">​</a></h1><p>原则：展示与新数据全用新名；凡硬改会断存量（.env、已发链接、磁盘状态、 内核活规则）的，一律双读/双发/迁移清理，过渡完成面与新名一致。</p><h2 id="后端-盘点-a-go-backend-go-gost-58-文件命中" tabindex="-1">后端（盘点 A：go-backend + go-gost，58 文件命中） <a class="header-anchor" href="#后端-盘点-a-go-backend-go-gost-58-文件命中" aria-label="Permalink to &quot;后端（盘点 A：go-backend + go-gost，58 文件命中）&quot;">​</a></h2><h3 id="直接改" tabindex="-1">直接改 <a class="header-anchor" href="#直接改" aria-label="Permalink to &quot;直接改&quot;">​</a></h3><ul><li>展示：app_name 种子与兜底（repository.go:529、kernel_relay.go:653、 notify.go:118）现行值 FLVX-MAX → FLMX；Passkey RPDisplayName（passkey.go:62）</li><li>日志前缀 <code>[flvx]</code>（go-gost/x/kernel manager/geodata、socket/process）、 nft runner 的 &quot;FLVX rules&quot; 文案</li><li>User-Agent <code>flvx-panel/1.0</code> → <code>flmx-panel/1.0</code>（secure_fetch.go:258）</li><li><code>FLVX-PING</code> 探测载荷 → <code>FLMX-PING</code>（接收方不校验内容）</li><li>仓库常量：handler/upgrade.go:26、go-gost/x/socket/websocket_reporter.go:1445 → iiiiiiiii7125-art/flmx-max（测试 system_upgrade_test.go 同步）</li></ul><h3 id="双读兼容-新名优先、旧名兜底" tabindex="-1">双读兼容（新名优先、旧名兜底） <a class="header-anchor" href="#双读兼容-新名优先、旧名兜底" aria-label="Permalink to &quot;双读兼容（新名优先、旧名兜底）&quot;">​</a></h3><ul><li>环境变量 6 个运行时 + 1 个测试专用：FLMX_TRUSTED_PROXY_HOPS、 FLMX_FETCH_ALLOW_PRIVATE_NETWORKS、FLMX_FETCH_PRIVATE_ALLOWLIST、 FLMX_FEDERATION_TRUSTED_PROXIES、FLMX_WEBAUTHN_ORIGIN（后端）； FLMX_KERNEL_DIR（agent）；FLVX_POSTGRES_TEST_DSN（CI/测试，直接改名）</li><li>订阅签名：新增 <code>flmx-subsig-v3</code> 生成新链接；校验 v3→v2→v1 三代通吃 （user_inbound.go），存量链接不断</li><li>流量上报头：agent 双发 <code>X-Flmx-Seq</code> + <code>X-Flvx-Seq</code>；面板先读新头回退旧头</li><li>agent seq 文件 <code>flvx_agent_seq.json</code> → <code>flmx_agent_seq.json</code>，新文件缺失时 读旧文件迁移（防 seq 重置导致重复计账）</li><li>内核用户标识：渲染改 <code>u%d@flmx</code> / <code>flmx-u%d</code>（users.go:17,163），流量 归属解析双认 flmx/flmx 两种前缀，过渡期新旧配置并存不丢账</li></ul><h3 id="改名-清理-legacy-防残留生效" tabindex="-1">改名 + 清理 legacy（防残留生效） <a class="header-anchor" href="#改名-清理-legacy-防残留生效" aria-label="Permalink to &quot;改名 + 清理 legacy（防残留生效）&quot;">​</a></h3><ul><li>nft 表：面板 <code>inet flvx</code> → <code>inet flmx</code>、节点 <code>flvx_kernel</code> → <code>flmx_kernel</code>； 应用/启动路径显式删除 legacy 表，否则旧表在内核继续生效</li><li>sysctl 调优文件 <code>/etc/sysctl.d/99-flvx-tuning.conf</code> → <code>99-flmx-tuning.conf</code>， 写入时顺带删除旧文件（99-flmx 字典序在前，残留旧文件会静默覆盖新值）</li><li>部署目录探测：<code>/opt/flmx-panel</code> 优先、<code>/opt/flvx-panel</code> 兜底 （system_upgrade.go:28，存量面板装在旧目录）</li><li>升级状态文件 <code>.flvx_upgrade_status.json</code> → <code>.flmx_upgrade_status.json</code> （Go 与生成的 helper 脚本同改；读时回退旧名）</li><li>GH 镜像缓存目录 <code>flvx-github-cache</code> → <code>flmx-github-cache</code>（旧缓存孤儿无害）</li><li>升级 helper 临时名 <code>flvx-upgrade-helper-%d</code> → <code>flmx-…</code></li></ul><h3 id="不动" tabindex="-1">不动 <a class="header-anchor" href="#不动" aria-label="Permalink to &quot;不动&quot;">​</a></h3><ul><li>FLUX_ 族（flux_agent 二进制/服务名、/etc/flux_agent/、FLUX_VERSION）： 不是 FLVX 字样，且牵动每台节点的 systemd 与安装路径，另行立项</li><li>JWT（无品牌串；密钥文件名 jwt_secret 与品牌无关）</li></ul><h2 id="前端-盘点-b-vite-frontend-51-处命中-21-文件" tabindex="-1">前端（盘点 B：vite-frontend，51 处命中 / 21 文件） <a class="header-anchor" href="#前端-盘点-b-vite-frontend-51-处命中-21-文件" aria-label="Permalink to &quot;前端（盘点 B：vite-frontend，51 处命中 / 21 文件）&quot;">​</a></h2><h3 id="直接改-1" tabindex="-1">直接改 <a class="header-anchor" href="#直接改-1" aria-label="Permalink to &quot;直接改&quot;">​</a></h3><ul><li>index.html 标题/meta、vite.config.ts 的 PWA manifest、site.ts 站点名默认 与兜底（现行 FLVX-MAX → FLMX）、version-footer 页脚字样、config.tsx 文案、 主题元数据（FLVX Team/Community → FLMX Team/Community）、package.json 包名</li><li>仓库 URL：.env.production:1 与 site.ts:33 → flmx-max（GitHub 重定向兜底）</li><li>转发导入格式判别符 <code>&quot;flvx&quot;</code> → <code>&quot;flmx&quot;</code> + UI 标签（判别符从不写入导出 文件内容，旧文件导入不受影响——盘点 B 已证）</li></ul><h3 id="本地存储键-无一存凭证-token-键为裸-token-站点缓存为-vite-config" tabindex="-1">本地存储键（无一存凭证：token 键为裸 &quot;token&quot;，站点缓存为 vite_config_） <a class="header-anchor" href="#本地存储键-无一存凭证-token-键为裸-token-站点缓存为-vite-config" aria-label="Permalink to &quot;本地存储键（无一存凭证：token 键为裸 &quot;token&quot;，站点缓存为 vite_config_）&quot;">​</a></h3><ul><li>全部 flvx* 键改 flmx*；其中主题两键（<code>flvx:theme</code> 三处耦合含 index.html 内联引导脚本、<code>flvx:active-theme</code> 含 context.tsx:123 字面量删除点）加 一次性回退读旧键，无感迁移；其余键（公告已读、入站/中转标签与分组） 硬改，后果上限为偏好重置一次</li><li>内部标识 <code>data-flvx-theme</code>（5 处耦合）与 <code>@keyframes flvx-scanline</code> 原子同改</li></ul><p>（脚本/工作流/文档部分待盘点 C 回收后补入本文件。）</p><h2 id="脚本-工作流-文档-盘点-c-实施侧全量扫校" tabindex="-1">脚本 / 工作流 / 文档（盘点 C + 实施侧全量扫校） <a class="header-anchor" href="#脚本-工作流-文档-盘点-c-实施侧全量扫校" aria-label="Permalink to &quot;脚本 / 工作流 / 文档（盘点 C + 实施侧全量扫校）&quot;">​</a></h2><h3 id="直接改-2" tabindex="-1">直接改 <a class="header-anchor" href="#直接改-2" aria-label="Permalink to &quot;直接改&quot;">​</a></h3><ul><li>仓库地址：install.sh:31、panel_install.sh:11 的 REPO 常量、README 与 doc 全部链接、VitePress base <code>/flvx-max/</code> → <code>/flmx-max/</code>； 工作流中的仓库地址本就动态取 <code>github.repository</code>，改名后自动适配</li><li>GHCR 镜像：<code>flvx-flux-panel-backend</code> / <code>flvx-vite-frontend</code> → <code>flmx-flux-panel-backend</code> / <code>flmx-vite-frontend</code>（docker-build.yml 的 构建标签、compose 注入、冒烟拉取与根目录两份 compose 同步）；面板升级 时新 compose 整体替换，镜像切换随之生效，旧镜像留存 GHCR 无害</li><li>compose 容器侧部署路径 <code>/opt/flvx-panel</code> → <code>/opt/flmx-panel</code> （PANEL_DEPLOY_DIR 与挂载目标同改；宿主机目录不变）。panel_install.sh 的 .env 探测列表双认两个路径</li><li>compose 的 Passkey 环境透传改双名：<code>FLMX_WEBAUTHN_ORIGIN</code>（带旧名 展开兜底）与旧名键并列，避免新装用户按新文档设新名却透不进容器</li><li>技能包：目录 skills/flvx-api → skills/flmx-api，包名 @flvx/skill-api → @flmx/skill-api，publish-skill.yml 路径同步；包内与 doc/ai-skill.md 的 <code>FLVX_*</code> 示例环境变量、~/.flvx 目录约定同步改 FLMX_*/~/.flmx（纯文档）</li><li>doc/package.json 名 flvx-docs → flmx-docs；tests/e2e 的说明文字与包名</li></ul><h3 id="保留-有意的历史-法律-夹具" tabindex="-1">保留（有意的历史/法律/夹具） <a class="header-anchor" href="#保留-有意的历史-法律-夹具" aria-label="Permalink to &quot;保留（有意的历史/法律/夹具）&quot;">​</a></h3><ul><li>NOTICE（上游 FLVX 的法律归属声明，非本产品品牌）、doc/audit/* 与 docs/superpowers/<em>、plans/</em>、doc/BUILD_v1.0.0.md、doc/PORT-from-flyx.md （均为带日期的历史记录，不回改）</li><li>test-install-scripts-proxy.sh 中 &quot;flvx-panel&quot; 是模拟存量部署项目名的 夹具（验证升级保留既有项目名），保留原字面</li></ul><h2 id="实施中抓到的一个真坑-已修-测试锁死" tabindex="-1">实施中抓到的一个真坑（已修 + 测试锁死） <a class="header-anchor" href="#实施中抓到的一个真坑-已修-测试锁死" aria-label="Permalink to &quot;实施中抓到的一个真坑（已修 + 测试锁死）&quot;">​</a></h2><p>文案批量替换一度把 5 处 <code>config.GetEnvAny(&quot;FLMX_*&quot;, &quot;FLVX_*&quot;)</code> 的旧名兜底 参数也改成了新名（双读变单读）——被 health 包以旧名 env 运行的既有测试 当场抓出。已逐处修复，并新增 rename_compat_test.go（旧 env 兜底 + 新名 优先 + Passkey Origin 旧名 + 三代签名通吃）永久防回归。</p><h2 id="基线新增登记" tabindex="-1">基线新增登记 <a class="header-anchor" href="#基线新增登记" aria-label="Permalink to &quot;基线新增登记&quot;">​</a></h2><ul><li>tests/contract 的 TestPasskeyDiscoverableLoginAndOwnership 在干净 HEAD (559f0b6) 上同样失败（登录限流 429，合同测试间状态串扰），与改名无关， 2026-10-20 经 worktree 基线对照确认，登记为预存失败。</li></ul><h2 id="c-路交叉核对补遗-2026-10-20-21-40" tabindex="-1">C 路交叉核对补遗（2026-10-20 21:40） <a class="header-anchor" href="#c-路交叉核对补遗-2026-10-20-21-40" aria-label="Permalink to &quot;C 路交叉核对补遗（2026-10-20 21:40）&quot;">​</a></h2><p>C 报告与实施侧自查互核后补修三处：panel_install.sh 自读的 <code>FLVX_VERIFY_DOWNLOADS</code> 改双读（<code>${FLMX_VERIFY_DOWNLOADS:-${FLVX_…:-1}}</code>， A 路盘点只覆盖 Go 代码、实施侧 grep 漏检此项）；doc/guide/import.md 的 UA 描述 <code>flvx-panel/1.0</code> → <code>flmx-panel/1.0</code>；nodes.md 的调优文件名、 postgresql.md 的备份示例路径同步新名。C 报告其余高危项（卷名/容器名/ 项目名不动、Pages base、镜像同版切换、WEBAUTHN 三方一致）均已按其 结论落实或本来就未触碰。</p>',28)])])}const u=o(i,[["render",d]]);export{x as __pageData,u as default};
